code='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # A horizontal 5-line copies the adjoining perpendicular color sequence
    # across its span.
    seen = set()
    for r in range(h):
        c = 0
        while c < w:
            if g[r][c] != 5 or (r, c) in seen:
                c += 1
                continue
            a = c
            while c < w and g[r][c] == 5:
                seen.add((r, c)); c += 1
            b = c - 1
            for x in (a, b):
                for dr in (-1, 1):
                    rr = r + dr
                    vals = []
                    while 0 <= rr < h and g[rr][x] != 0 and g[rr][x] != 5:
                        vals.append((rr, g[rr][x]))
                        rr += dr
                    if vals:
                        for sr, color in vals:
                            for cc in range(a, b + 1):
                                if g[sr][cc] == 0:
                                    g[sr][cc] = color
                        break
                else:
                    continue
                break
    # A vertical 5-line copies the adjoining perpendicular row-pattern,
    # repeating a multi-row pattern along the line.
    seen = set()
    for c in range(w):
        r = 0
        while r < h:
            if g[r][c] != 5 or (r, c) in seen:
                r += 1
                continue
            a = r
            while r < h and g[r][c] == 5:
                seen.add((r, c)); r += 1
            b = r - 1
            for x in (c + 1, c - 1):
                if not 0 <= x < w:
                    continue
                rows = [rr for rr in range(h) if g[rr][x] != 0 and g[rr][x] != 5]
                # Select the contiguous seed block closest to the 5-line.
                blocks = []
                for rr in rows:
                    if not blocks or rr > blocks[-1][-1] + 1:
                        blocks.append([rr])
                    else:
                        blocks[-1].append(rr)
                blocks = [blk for blk in blocks if any(a <= rr <= b for rr in blk)]
                if not blocks:
                    continue
                block = min(blocks, key=lambda z: min(abs(rr-a) for rr in z))
                top, bottom = block[0], block[-1]
                patterns = []
                for rr in block:
                    rowvals = []
                    xx = x
                    step = 1 if x > c else -1
                    while 0 <= xx < w and g[rr][xx] not in (0, 5):
                        rowvals.append(g[rr][xx]); xx += step
                    if rowvals:
                        patterns.append(rowvals)
                if not patterns:
                    continue
                for rr in range(a, b + 1):
                    pat = patterns[(rr - top) % len(patterns)]
                    xx = x
                    step = 1 if x > c else -1
                    for color in pat:
                        if 0 <= xx < w and g[rr][xx] == 0:
                            g[rr][xx] = color
                        xx += step
                break
    return g
